</head><body><main>
  <h1>ScoreArena</h1>
  <p class="sub">桌面规则游戏与赛事管理</p>

  <h2>创建公开房间</h2>
  <form id="room-form" novalidate="">
    <div class="field">
      <label for="name">房间名称</label>
      <input id="name" name="name" type="text" autocomplete="off" placeholder="1–40 个字符，首尾空白会被去掉" required="">
      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
    </div>
    <div class="field">
      <label for="game">游戏规则</label>
      <select id="game" name="game" required="">
        <option value="" selected="">请选择游戏规则…</option>
        <option value="gomoku">五子棋（gomoku）</option>
        <option value="ludo">飞行棋（ludo）</option>
      </select>
    </div>
    <div class="field">
      <label for="capacity">人数上限</label>
      <select id="capacity" name="capacity" required="" disabled=""><option value="">请先选择游戏规则</option></select>
      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
    </div>
    <div class="field">
      <label for="turnSeconds">每步时间限制</label>
      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric" placeholder="秒，0 表示不限时" required="">
      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
    </div>
    <div class="field">
      <div></div>
      <div class="actions">
        <button type="submit" id="submit">创建房间</button>
      </div>
    </div>
    <p class="msg" id="form-msg" role="alert"></p>
  </form>

  <h2>房间列表</h2>
  <div id="list-area"><table><thead><tr><th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th><th>时间限制</th><th>状态</th><th>创建时间</th></tr></thead><tbody><tr><td class="id">room-2026-01</td><td>晚间对弈</td><td>constructor</td><td>2 人</td><td>不限时</td><td><span class="badge">toString</span></td><td title="2026-03-02T01:02:03Z">2026-03-02 09:02:03</td></tr><tr><td class="id">room-2026-02</td><td>周末约局</td><td>__proto__</td><td>4 人</td><td>60 秒</td><td><span class="badge">__proto__</span></td><td title="2026-03-02T02:03:04Z">2026-03-02 10:03:04</td></tr><tr><td class="id">room-2026-03</td><td>朋友对局</td><td>Gomoku</td><td>2 人</td><td>10 秒</td><td><span class="badge"> WAITING </span></td><td title="2026-03-02T03:04:05Z">2026-03-02 11:04:05</td></tr><tr><td class="id">room-2026-04</td><td>周末飞行棋</td><td>飞行棋</td><td>4 人</td><td>60 秒</td><td><span class="badge">未开始</span></td><td title="2026-03-02T04:05:06Z">2026-03-02 12:05:06</td></tr></tbody></table></div>

  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
</main>

<script>
(function () {
  var form = document.getElementById('room-form');
  var gameSel = document.getElementById('game');
  var capSel = document.getElementById('capacity');
  var capHint = document.getElementById('capacity-hint');
  var submitBtn = document.getElementById('submit');
  var formMsg = document.getElementById('form-msg');
  var listArea = document.getElementById('list-area');
  var emptyTip = document.getElementById('empty-tip');

  // 映射表必须是无原型对象：历史值里可能恰好存着 "constructor"、"toString"、
  // "__proto__" 这类字符串，普通对象字面量会沿原型链查到内置函数或
  // Object.prototype，反而把函数源码或 [object Object] 当成中文映射显示。
  // 无原型对象查这些键一律得到 undefined，于是按未知值逐字回显原文。
  var GAME_LABELS = Object.create(null);
  GAME_LABELS.gomoku = '五子棋';
  GAME_LABELS.ludo = '飞行棋';
  var STATUS_LABELS = Object.create(null);
  STATUS_LABELS.waiting = '未开始';

  // 按所选规则重建人数上限选项。
  function syncCapacity() {
    var game = gameSel.value;
    var prev = capSel.value;
    capSel.innerHTML = '';
    if (game === 'gomoku') {
      capSel.disabled = false;
      addOption('', '固定 2 人');
      addOption('2', '2 人');
      capSel.value = '2';
      capHint.textContent = '五子棋人数上限固定为 2 人。';
    } else if (game === 'ludo') {
      capSel.disabled = false;
      addOption('', '请选择人数上限…');
      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
    } else {
      capSel.disabled = true;
      addOption('', '请先选择游戏规则');
      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
    }
  }

  function addOption(value, text) {
    var opt = document.createElement('option');
    opt.value = value;
    opt.textContent = text;
    capSel.appendChild(opt);
  }

  gameSel.addEventListener('change', syncCapacity);

  function showMessage(kind, text) {
    formMsg.className = 'msg show ' + kind;
    formMsg.textContent = text;
  }
  function clearMessage() {
    formMsg.className = 'msg';
    formMsg.textContent = '';
  }

  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
  function trimName(value) {
    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
  }

  // 与服务端一致的提交前校验；服务端仍会再次校验。
  // 输入表单原始值，返回 { error } 或 { payload }：漏填要明确报错，绝不补默认值；
  // 名称只含会被去掉的首尾空白时同样视为空。通过校验的 payload 中名称仍是
  // 用户原始输入（不由页面整理），时间与人数各只转换一次。
  function checkForm(raw) {
    var nameLen = Array.from(trimName(raw.name)).length;
    if (nameLen === 0) return { error: '房间名称不能为空。' };
    if (!raw.game) return { error: '请选择游戏规则。' };
    if (raw.capacity === '') return { error: '请选择人数上限。' };
    if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };
    if (!/^-?\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };

    // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。
    var capacity = parseInt(raw.capacity, 10);
    var turnSeconds = Number(raw.turnSeconds);

    if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };
    if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };
    if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };
    if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {
      return { error: '飞行棋的人数上限必须为 2 至 4 人。' };
    }
    if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {
      return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };
    }

    return {
      payload: {
        name: raw.name,
        game: raw.game,
        capacity: capacity,
        turnSeconds: turnSeconds
      }
    };
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearMessage();

    var result = checkForm({
      name: document.getElementById('name').value,
      game: gameSel.value,
      capacity: capSel.value,
      turnSeconds: document.getElementById('turnSeconds').value.trim()
    });
    if (result.error) { showMessage('error', result.error); return; }

    submit(result.payload);
  });

  function submit(payload) {
    submitBtn.disabled = true;
    fetch('/api/rooms', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function (resp) {
      return resp.json().catch(function () { return {}; }).then(function (data) {
        return { ok: resp.ok, status: resp.status, data: data };
      });
    }).then(function (result) {
      if (result.ok && result.status === 201) {
        showMessage('ok', '房间已创建，编号：' + result.data.id);
        form.reset();
        syncCapacity();
        return loadRooms();
      }
      // 创建失败：保留填写内容，仅显示原因。
      var reason = result.data && result.data.error ? result.data.error
                 : ('创建失败（HTTP ' + result.status + '）');
      showMessage('error', reason);
    }).catch(function () {
      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
    }).finally(function () {
      submitBtn.disabled = false;
    });
  }

  // 创建时间列的三种正常展示（对象/数组已由 buildRoomRow 统一判为异常，
  // 不会进入这里）：
  //   1. 能解析成有效日期的字符串：按浏览器本地时区显示
  //      YYYY-MM-DD HH:mm:ss（带时区偏移的时间换算成实际对应的本地时刻，
  //      不把原串里的时分当本地时间），悬浮提示保留接口返回的原始字符串；
  //   2. 无法解析的非空字符串：原文直接显示在单元格中（textContent 保证
  //      尖括号等字符只作为文字呈现），不替换为当前时间，不附悬浮说明；
  //   3. 字段缺失、null 或空字符串：单元格留空且没有悬浮说明，
  //      绝不由页面生成 undefined 或 Invalid Date。
  function renderTimeCell(td, value) {
    if (value == null || value === '') return;

    var d = new Date(value);
    if (isNaN(d.getTime())) {
      td.textContent = typeof value === 'string' ? value : String(value);
      return;
    }

    var pad = function (n) { return String(n).padStart(2, '0'); };
    td.textContent = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    td.title = typeof value === 'string' ? value : String(value);
  }

  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
  function isRoomRecord(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function appendSkipNotice(skipped, allSkipped) {
    var p = document.createElement('p');
    p.className = 'skip-notice';
    if (allSkipped) {
      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
    } else {
      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
        '原始数据仍保留在服务端，未被删除或改写。';
    }
    listArea.appendChild(p);
  }

  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
  // 异常，仍走各列原有的展示与兜底。
  var BAD_FIELD_TEXT = '字段格式异常';
  function isAbnormalField(value) {
    return value !== null && typeof value === 'object';
  }
  function markBadCell(td) {
    td.textContent = BAD_FIELD_TEXT;
  }

  function appendBadge(td, text) {
    var badge = document.createElement('span');
    badge.className = 'badge';
    badge.textContent = text;
    td.appendChild(badge);
  }

  // 七列的展示定义，顺序即表格列顺序（表头也由同一份定义生成）。每列只
  // 描述“正常值如何显示”（含各列原有的兜底行为）；对象/数组的异常判定
  // 与替换由 buildRoomRow 统一处理，不在各列重复维护。个别列可用
  // renderBad 保留原有容器（如状态列的徽标），缺省时整格替换为异常文案。
  var ROOM_COLUMNS = [
    {
      key: 'id',
      label: '房间编号',
      className: 'id',
      render: function (td, value) { td.textContent = value || ''; }
    },
    {
      key: 'name',
      label: '名称',
      render: function (td, value) { td.textContent = value || ''; }
    },
    {
      key: 'game',
      label: '规则',
      render: function (td, value) {
        td.textContent = GAME_LABELS[value] || value || '';
      }
    },
    {
      key: 'capacity',
      label: '人数上限',
      render: function (td, value) {
        td.textContent = (value != null ? value : '') + ' 人';
      }
    },
    {
      key: 'turnSeconds',
      label: '时间限制',
      render: function (td, value) {
        td.textContent = value === 0 ? '不限时' : value + ' 秒';
      }
    },
    {
      key: 'status',
      label: '状态',
      render: function (td, value) {
        appendBadge(td, STATUS_LABELS[value] || value || '');
      },
      // 异常状态仍在原有徽标中显示提示文案。
      renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }
    },
    {
      key: 'createdAt',
      label: '创建时间',
      render: renderTimeCell
      // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明
      // （不设置 title）。
    }
  ];

  // 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
  function buildRoomRow(r) {
    var tr = document.createElement('tr');
    ROOM_COLUMNS.forEach(function (col) {
      var td = document.createElement('td');
      if (col.className) td.className = col.className;
      var value = r[col.key];
      if (isAbnormalField(value)) {
        if (col.renderBad) col.renderBad(td);
        else markBadCell(td);
      } else {
        col.render(td, value);
      }
      tr.appendChild(td);
    });
    return tr;
  }

  function renderRooms(rooms) {
    listArea.innerHTML = '';

    var validRooms = [];
    var skipped = 0;
    rooms.forEach(function (r) {
      if (isRoomRecord(r)) validRooms.push(r);
      else skipped++;
    });

    if (!validRooms.length) {
      if (skipped > 0) {
        appendSkipNotice(skipped, true);
      } else {
        var pEmpty = document.createElement('p');
        pEmpty.className = 'empty';
        pEmpty.textContent = '还没有房间记录。';
        listArea.appendChild(pEmpty);
      }
      return;
    }

    if (skipped > 0) appendSkipNotice(skipped, false);

    var table = document.createElement('table');
    var thead = document.createElement('thead');
    var headRow = document.createElement('tr');
    ROOM_COLUMNS.forEach(function (col) {
      var th = document.createElement('th');
      th.textContent = col.label;
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);
    var tbody = document.createElement('tbody');
    validRooms.forEach(function (r) {
      tbody.appendChild(buildRoomRow(r));
    });
    table.appendChild(tbody);
    listArea.appendChild(table);
  }

  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
  // 防止旧数据覆盖新查询已展示的列表。
  var listQuerySeq = 0;

  function loadRooms() {
    var seq = ++listQuerySeq;
    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
      .then(function (resp) {
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        return resp.json();
      })
      .then(function (data) {
        if (seq !== listQuerySeq) return;
        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
        renderRooms(rooms);
      })
      .catch(function () {
        if (seq !== listQuerySeq) return;
        listArea.innerHTML = '';
        var p = document.createElement('p');
        p.className = 'list-error';
        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
        listArea.appendChild(p);
      });
  }

  syncCapacity();
  loadRooms();
})();
</script>

